// Dongguk University, Seoul campus (동국대학교 서울캠퍼스, 서울 중구 필동, 남산 자락). Data is generated by scripts/campuses/dongguk/build-package.mjs
// from the pilot (pilot/dongguk-seoul): the destructible models of active-models.json (본관·명진관 detailed, the rest generic; 명진관·문화관
// break like every university building), 정각원 (법당) and 범종각 as protected shield models (religious, rule 10.1, user decision 10-22),
// a baked ground drawn with the pilot's ground shader (the SKKU port src/campuses/skku/ground-look.js; the pilot's final-materials.js is
// the uos-seoul-v2 shader), the preview's own retaining walls / ribbons (R3 zone rule) / skirts and planting (same trees), the place
// models of landscape/layout.json (팔정도 부처님 성상 틀·코끼리상·연못·석탑, 정각원 대계단·석등, 정문, 스탠드 - never damaged) +
// landscape/sports.gltf, and the non-destructible context (필동, 장충동, 남산) fading into the haze. Local only until the user approves
// (registry public: false).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, DONGGUK_PLACEMENTS, DONGGUK_BUILDING_BASE, DONGGUK_HEIGHT_GRIDS, DONGGUK_HEIGHT_RANGE_M, DONGGUK_ENV_IDS, DONGGUK_ENV_MANIFEST_IDS, DONGGUK_LOOK, DONGGUK_ZONES, DONGGUK_DISPLAY, DONGGUK_PROVENANCE } from './data.js';
import { DONGGUK_FOOTPRINTS } from './footprints.js';
import { DONGGUK_PROTECTED } from './protected.js';
import { createSkkuGroundLook } from '../skku/ground-look.js';

const MODEL_IDS = Object.freeze(DONGGUK_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/dongguk/${file}`, import.meta.url).href;
const HAZE = DONGGUK_DISPLAY.haze, FADE = DONGGUK_DISPLAY.fade;

export const DONGGUK = Object.freeze({
  id: 'dongguk',
  meta: Object.freeze({ school: '동국대학교', campus: '서울캠퍼스', short: '동국대', modelNoun: '동국대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: DONGGUK_PLACEMENTS,
  approvedCount: DONGGUK_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['myungjin', 'mainHall', 'library', 'manhae', 'dahyang'].filter(id => MODEL_IDS.includes(id))),
  startBuildingId: 'myungjin',
  // Start: from over the north side of 팔정도 (the origin, E 0 / N 0) looking south: 부처님 성상 틀 (E -3 / N -16) in the middle, 명진관 and its
  // central tower (E -19 / N -68) behind it, 본관 / 다향관 / 만해관 around the plaza, 정각원 and 남산 beyond.
  // Box in world units (metres x 0.5, z = -N): E -44..28 m, N -80..24 m, 0..26 m high; azimuth 2.95 = camera north, a little east, looking
  // south. Projected in Node with src/camera.js (scripts/campuses/dongguk/start-frame-check.mjs, W1 2026-10-22): camera at E 24 / N 136 m,
  // 90 m up (1280x800; E 54 / N 291, 164 m up at 390x844); 성상 틀 top at screen (622, 457) / (185, 454), 명진관 roof (tower) at
  // (658, 247) / (205, 334), inside the HUD-free band 96..712 / 96..756; campus buildings' share of the band 0.45 / 0.26, 11 / 7 of 28 on screen.
  view: Object.freeze({ startFrame: Object.freeze({ min: Object.freeze([-22, -1, -12]), max: Object.freeze([14, 13, 40]), azimuth: 2.95 }) }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: DONGGUK_ENV_MANIFEST_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: DONGGUK_HEIGHT_GRIDS, buildingBase: DONGGUK_BUILDING_BASE,
    source: 'Relative terrain estimate (Copernicus GLO-30, building-filled, forest lowered + floor-link / photo level evidence, pilot/dongguk-seoul); not a survey' }),
  environment: Object.freeze({ provenance: DONGGUK_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, planting and the place models estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: DONGGUK_ENV_IDS, castShadow: Object.freeze([]), materialHook: createSkkuGroundLook(DONGGUK_LOOK, DONGGUK_ZONES),
      // context.json display fade (preview.js FADE): campus clear to r0, the backdrop melts into the haze by r1
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, ...(FADE.linearShare ? { linear: FADE.linearShare } : {}), colour: HAZE }), playMargin_m: 30,
      source: 'pilot/dongguk-seoul preview ground + planting + landscape + context, baked' }),
  }),
  // Protected (pilot destructible:false: 정각원, 범종각 - religious, user decision 10-22): never destructible; weapons meet the protective
  // shield (src/protected-buildings.js); own manifest, models packed with the campus cache.
  protected: Object.freeze({
    ...(DONGGUK_PROTECTED.length ? { manifestURL: asset('protected/manifest.json') } : {}),
    models: DONGGUK_PROTECTED,
  }),
  // Hazard tape around every destructible building only (src/engine/hazard-tape.js): none on the protected models or the context.
  hazardTape: Object.freeze({ footprints: DONGGUK_FOOTPRINTS }),
  scene: Object.freeze({
    // preview.js: hemisphere (#fff, #7d8a78, 1.35), sun #fff4e2 3.1 from (-220, 340, 280) towards (0, 10, 0) -> that direction, halved
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 700, far: 2400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 260 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: DONGGUK_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default DONGGUK;
